#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, M;

    if (scanf("%d %d", &N, &M) != 2) return 0;

    unsigned int adj[20];
    for (int i = 0; i < N; i++) adj[i] = 0;

    for (int i = 0; i < M; i++) {
        int x, y;
        if (scanf("%d %d", &x, &y) != 2) break;
        x--; y--;
        adj[x] |= 1u << y;
        adj[y] |= 1u << x;
    }

    int total = 1 << N;
    long long *f = (long long *)malloc(sizeof(long long) * (size_t)total);
    if (!f) return 0;

    /* f[S] = numero de subconjuntos independentes contidos em S (incluindo vazio) */
    f[0] = 1;

    for (int S = 1; S < total; S++) {
        int v = __builtin_ctz((unsigned int)S);          /* menor ingrediente presente em S */
        unsigned int rest = ((unsigned int)S) ^ (1u << v);
        /*conjuntos sem v: f[rest]; conjuntos com v: v e seus vizinhos em S ficam de fora */
        f[S] = f[rest] + f[rest & ~adj[v]];
    }

    printf("%lld\n", f[total - 1] - 1);   /* subtrai o sanduiche vazio */

    free(f);
    return 0;
}
